fn solve(cafes: Vec<i8>) -> i8 {
    // Use a hashmap to store the last occurrence index of each value
    use std::collections::HashMap;
    
    let mut last_positions = HashMap::new();
    
    // Iterate through the array, updating the last occurrence index for each value
    for (index, &value) in cafes.iter().enumerate() {
        last_positions.insert(value, index);
    }
    
    // Find the value with the minimal last occurrence index
    // Since the array is non-empty, unwrap is safe
    let (result, _) = last_positions
        .iter()
        .min_by_key(|&(_, &pos)| pos)
        .unwrap();
    
    *result
}

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Find the last occurrence of cafe in the array
    cafes
        .iter()
        .enumerate()
        .rev()  // Search from the end
        .find(|&(_, &value)| value == cafe)
        .map(|(index, _)| index)
        .unwrap()  // Since cafe is guaranteed to be in the array per problem context
}